const raw = $input.first().json;
const body = raw.body ?? raw;

const conexaoId = body.conexaoId || body.conexao_id;
const templateId = body.templateId || body.template_id;

if (!conexaoId) throw new Error('Campo conexaoId obrigatorio.');
if (!templateId) throw new Error('Campo templateId obrigatorio.');

return [{ json: { conexaoId, templateId } }];

const entrada = $('VALIDAR ENTRADA').first().json;
const conexao = $input.first().json;

if (!conexao?.access_token || !conexao?.waba_id) {
  throw new Error('Conexao nao encontrada em SAAS_Conexoes.');
}

if (!conexao.apiOficial) {
  throw new Error('Conexao nao e API Oficial.');
}

return [
  {
    json: {
      ...entrada,
      access_token: conexao.access_token,
      waba_id: conexao.waba_id
    }
  }
];

const mesclar = $('MESCLAR CONEXAO').first().json;
const template = $input.first().json;

if (!template?.id) {
  throw new Error('Template nao encontrado em SAAS_Templates_Meta.');
}

if (String(template.conexaoId) !== String(mesclar.conexaoId)) {
  throw new Error('Template nao pertence a esta conexao.');
}

return [
  {
    json: {
      conexaoId: mesclar.conexaoId,
      access_token: mesclar.access_token,
      waba_id: mesclar.waba_id,
      templateId: template.id,
      nome: template.nome,
      idioma: template.idioma,
      metaTemplateId: template.metaTemplateId || null
    }
  }
];

const prev = $input.first().json;
const qs = { name: prev.nome };

if (prev.metaTemplateId) {
  qs.hsm_id = prev.metaTemplateId;
}

let metaExcluido = false;
let metaAviso = null;

try {
  const res = await this.helpers.httpRequest({
    method: 'DELETE',
    url: `https://graph.facebook.com/v25.0/${prev.waba_id}/message_templates`,
    qs,
    headers: { Authorization: `Bearer ${prev.access_token}` },
    json: true
  });

  if (res.error) {
    const msg = res.error.message || res.error.error_user_msg || '';
    const notFound = /not found|does not exist|nao encontrado|não encontrado/i.test(msg);
    if (notFound) {
      metaAviso = msg || 'Template ja inexistente na Meta.';
    } else {
      throw new Error(msg || 'Falha ao excluir template na Meta.');
    }
  } else if (res.success) {
    metaExcluido = true;
  } else {
    throw new Error('Falha ao excluir template na Meta.');
  }
} catch (error) {
  const msg = error.message || String(error);
  const notFound = /not found|does not exist|404|nao encontrado|não encontrado/i.test(msg);
  if (notFound) {
    metaAviso = msg;
  } else {
    throw error;
  }
}

return [
  {
    json: {
      ...prev,
      metaExcluido,
      metaAviso
    }
  }
];

const prev = $('EXCLUIR TEMPLATE META').first().json;

return [
  {
    json: {
      ok: true,
      conexaoId: prev.conexaoId,
      templateId: prev.templateId,
      nome: prev.nome,
      idioma: prev.idioma,
      metaTemplateId: prev.metaTemplateId,
      metaExcluido: prev.metaExcluido,
      metaAviso: prev.metaAviso,
      supabaseExcluido: true
    }
  }
];
